<?php
namespace App\Http\Controllers;
use App\Models\QueueAudit;
use App\Models\QueueTicket;
use App\Models\ServiceLocation;
use App\Models\ServiceCategory;
use App\Models\ServiceCounter;
use App\Services\QueueRegistrar;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class QueueController extends Controller {
 public function home(){return view('queue.home',['locations'=>ServiceLocation::where('active',true)->with(['categories'=>fn($q)=>$q->where('active',true)])->get()]);}
 public function register(Request $request,ServiceLocation $location,QueueRegistrar $registrar){$data=$request->validate(['service_category_id'=>'required|integer|exists:service_categories,id','customer_name'=>'nullable|string|max:120','customer_phone'=>'nullable|string|max:30']);$ticket=$registrar->register($location,ServiceCategory::findOrFail($data['service_category_id']),$request->user(),$data['customer_name']??null,$data['customer_phone']??null);return redirect()->route('queue.ticket',$ticket->lookup_token)->with('status','Queue ticket created.');}
 public function ticket(string $token){$ticket=QueueTicket::where('lookup_token',$token)->with('location','category','counter')->firstOrFail();return view('queue.ticket',compact('ticket'));}
 public function display(ServiceLocation $location){$today=now()->toDateString();$called=QueueTicket::where('service_location_id',$location->id)->whereDate('queue_date',$today)->whereIn('status',['called','serving'])->with('counter')->latest('called_at')->take(6)->get();$waiting=QueueTicket::where('service_location_id',$location->id)->whereDate('queue_date',$today)->where('status','waiting')->count();return view('queue.display',compact('location','called','waiting'));}
 public function dashboard(Request $request){if(!$request->user()?->isStaff())return redirect()->route('queue.home');$locations=ServiceLocation::where('active',true)->with('counters')->get();$location=$locations->firstWhere('id',$request->integer('location'))??$locations->first();abort_unless($location,404);$queues=QueueTicket::where('service_location_id',$location->id)->whereDate('queue_date',now()->toDateString())->with('category','counter')->orderByRaw("CASE status WHEN 'serving' THEN 0 WHEN 'called' THEN 1 WHEN 'waiting' THEN 2 ELSE 3 END")->orderBy('daily_number')->paginate(30)->withQueryString();return view('queue.dashboard',compact('locations','location','queues'));}
 public function next(Request $request,ServiceLocation $location){$user=$this->staff($request);$data=$request->validate(['counter_id'=>'required|integer']);$counter=ServiceCounter::where('service_location_id',$location->id)->where('active',true)->findOrFail($data['counter_id']);return DB::transaction(function()use($location,$counter,$user){$ticket=QueueTicket::where('service_location_id',$location->id)->whereDate('queue_date',now()->toDateString())->where('status','waiting')->orderBy('daily_number')->lockForUpdate()->first();if(!$ticket)return back()->with('status','No waiting queue.');$ticket->update(['status'=>'called','service_counter_id'=>$counter->id,'called_at'=>now()]);QueueAudit::create(['queue_ticket_id'=>$ticket->id,'user_id'=>$user->id,'action'=>'called','details'=>['counter'=>$counter->code]]);return back()->with('status','Called '.$ticket->display_number);});}
 public function transition(Request $request,int $id){$user=$this->staff($request);$data=$request->validate(['action'=>'required|in:recall,serve,complete,cancel']);return DB::transaction(function()use($id,$data,$user){$ticket=QueueTicket::whereDate('queue_date',now()->toDateString())->lockForUpdate()->findOrFail($id);$map=['recall'=>['called','called'],'serve'=>['called','serving'],'complete'=>['serving','completed'],'cancel'=>[['waiting','called'],'cancelled']];[$from,$to]=$map[$data['action']];if(!in_array($ticket->status,(array)$from,true))throw ValidationException::withMessages(['action'=>'Invalid queue transition.']);$stamp=match($to){'serving'=>['serving_at'=>now()],'completed'=>['completed_at'=>now()],'called'=>['called_at'=>now()],default=>[]};$ticket->update(['status'=>$to,...$stamp]);QueueAudit::create(['queue_ticket_id'=>$ticket->id,'user_id'=>$user->id,'action'=>$data['action'],'details'=>['status'=>$to]]);return back()->with('status','Queue '.$ticket->display_number.' updated.');});}
 public function report(Request $request){$this->staff($request);$request->validate(['date'=>'nullable|date']);$date=$request->date('date')?->toDateString()??now()->toDateString();$summary=QueueTicket::whereDate('queue_date',$date)->select('service_location_id','status',DB::raw('count(*) as total'))->groupBy('service_location_id','status')->with('location')->get();return view('queue.report',compact('summary','date'));}
 private function staff(Request $request){abort_unless($request->user()?->isStaff(),403);return $request->user();}
}
